import cv2,numpy as np
im=cv2.imread('first_frame.png'); rgb=im[:,:,::-1]
# generate annotated grid images with line/coordinates, to potentially use image preview unavailable; instead print structural color map per object
# For each row, find continuous runs satisfying red, yellow, dark, bright-neutral in region x0..256
r,g,b=[rgb[:,:,i].astype(int) for i in range(3)]; mx=rgb.max(2); mn=rgb.min(2)
masks={'R':(r>90)&(r>g*1.6)&(r>b*1.6),'Y':(r>g*1.02)&(g>b*1.18)&(r>75)&((mx-mn)>20),'K':(mx<75)&((mx-mn)<30),'S':(mx>135)&((mx-mn)<25)}
for y in [20,30,40,50,60,70,75,80,85,90,100,110,120,130,140,150,160,170,180,185]:
 s=''
 for x in range(0,256,2):
  found=[]
  for k,m in masks.items():
   if m[y,x:x+2].mean()>.5:found.append(k)
  s+=found[0] if found else ' '
 print(f'{y:03d} {s}')
PY"

